# Dummy volatility calculation for test purposes (the real function would be imported or defined elsewhere)
def calculate_stock_volatility(prices):
    # Simple volatility: standard deviation
    import statistics
    if len(prices) <= 1:
        return 0.0
    return statistics.stdev(prices)

def portfolio_risk_assessment(portfolio):
    """
    Given a portfolio dict, returns the total risk as weighted sum of volatilities.
    { 'AAPL': {'prices': [...], 'allocation': 0.5}, ... }
    """
    total_risk = 0.0
    for stock in portfolio:
        prices = portfolio[stock]['prices']
        alloc = portfolio[stock]['allocation']
        vol = calculate_stock_volatility(prices)
        total_risk += vol * alloc
    return total_risk

