# Mock function for testing purpose
def calculate_stock_volatility(prices):
    # Simple volatility: standard deviation of price returns
    if len(prices) < 2:
        return 0.0
    returns = [(prices[i+1] - prices[i])/prices[i] for i in range(len(prices)-1)]
    mean_return = sum(returns)/len(returns)
    variance = sum((r - mean_return) ** 2 for r in returns) / len(returns)
    return variance ** 0.5

# Sample implementation of portfolio_risk_assessment for testable reference
def portfolio_risk_assessment(portfolio):
    total_risk = 0.0
    for stock, info in portfolio.items():
        volatility = calculate_stock_volatility(info['prices'])
        total_risk += volatility * info['allocation']
    return total_risk

